package repository.db;

import exceptions.RepositoryException;
import model.User;
import repository.Repository;
import validators.Validator;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

/**
 * Database repository for users, implemented with JDBC.
 * Every operation is a query on the table users(id, first_name, last_name, email, password);
 * nothing is kept in memory. The id of a new user is generated by the database.
 */
public class UserDbRepository implements Repository<Long, User> {

    private final Validator<User> validator;
    private final String url;
    private final String username;
    private final String password;

    /**
     * @param validator - the validation strategy for users
     * @param url       - the JDBC url of the database (db.url)
     * @param username  - the database user (db.user)
     * @param password  - the password of the database user (db.password)
     */
    public UserDbRepository(Validator<User> validator, String url, String username, String password) {
        this.validator = validator;
        this.url = url;
        this.username = username;
        this.password = password;
    }

    /**
     * builds a user from the current row of a result set
     *
     * @param resultSet - the result set, positioned on a row of the table users
     * @return the user from the current row, with its id set
     * @throws SQLException if a column cannot be read
     */
    private User extractUser(ResultSet resultSet) throws SQLException {
        User user = new User(resultSet.getString("first_name"),
                resultSet.getString("last_name"),
                resultSet.getString("email"),
                resultSet.getString("password"));
        user.setId(resultSet.getLong("id"));
        return user;
    }

    /**
     * @param id - the id of the user; must not be null
     * @return the user with the given id or null if there is no such user
     * @throws IllegalArgumentException if id is null
     * @throws RepositoryException      if a database access error occurs
     */
    @Override
    public User findOne(Long id) {
        if (id == null) {
            throw new IllegalArgumentException("id must not be null");
        }
        String sql = "SELECT * FROM users WHERE id = ?";
        try (Connection connection = DriverManager.getConnection(url, username, password);
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setLong(1, id);                       // primul ? primeste id-ul
            try (ResultSet resultSet = statement.executeQuery()) {
                return resultSet.next() ? extractUser(resultSet) : null;
            }
        } catch (SQLException e) {
            throw new RepositoryException("Database error while searching user " + id + ": " + e.getMessage(), e);
        }
    }

    /**
     * @return all users, ordered by id
     * @throws RepositoryException if a database access error occurs
     */
    @Override
    public Iterable<User> findAll() {
        List<User> users = new ArrayList<>();
        String sql = "SELECT * FROM users ORDER BY id";
        try (Connection connection = DriverManager.getConnection(url, username, password);
             PreparedStatement statement = connection.prepareStatement(sql);
             ResultSet resultSet = statement.executeQuery()) {

            while (resultSet.next()) {                      // fiecare rand devine un User
                users.add(extractUser(resultSet));
            }
        } catch (SQLException e) {
            throw new RepositoryException("Database error while reading users: " + e.getMessage(), e);
        }
        return users;
    }

    /**
     * saves a new user; the id is generated by the database and set on the entity
     *
     * @param entity - the user to save; must not be null; its id is ignored
     * @return null - the user was saved (the generated id is now set on entity)
     * @throws IllegalArgumentException          if entity is null
     * @throws exceptions.ValidationException    if the user is not valid
     * @throws RepositoryException               if a database access error occurs
     *                                           or a constraint is violated (e.g. duplicate email)
     */
    @Override
    public User save(User entity) {
        if (entity == null) {
            throw new IllegalArgumentException("entity must not be null");
        }
        validator.validate(entity);                         // validare inainte de INSERT

        // id-ul NU apare in INSERT: il genereaza baza de date (GENERATED ALWAYS AS IDENTITY)
        String sql = "INSERT INTO users (first_name, last_name, email, password) VALUES (?, ?, ?, ?)";
        try (Connection connection = DriverManager.getConnection(url, username, password);
             PreparedStatement statement = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {

            statement.setString(1, entity.getFirstName());
            statement.setString(2, entity.getLastName());
            statement.setString(3, entity.getEmail());
            statement.setString(4, entity.getPassword());
            statement.executeUpdate();

            try (ResultSet keys = statement.getGeneratedKeys()) {   // randul inserat, cu id-ul generat
                if (keys.next()) {
                    entity.setId(keys.getLong("id"));
                }
            }
        } catch (SQLException e) {
            throw new RepositoryException("Database error while saving user: " + e.getMessage(), e);
        }
        return null;
    }

    /**
     * deletes the user with the given id
     *
     * @param id - the id of the user; must not be null
     * @return the deleted user or null if there is no user with the given id
     * @throws IllegalArgumentException if id is null
     * @throws RepositoryException      if a database access error occurs
     */
    @Override
    public User delete(Long id) {
        User found = findOne(id);                           // verifica si id == null
        if (found == null) {
            return null;
        }
        String sql = "DELETE FROM users WHERE id = ?";
        try (Connection connection = DriverManager.getConnection(url, username, password);
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setLong(1, id);
            statement.executeUpdate();
        } catch (SQLException e) {
            throw new RepositoryException("Database error while deleting user " + id + ": " + e.getMessage(), e);
        }
        return found;
    }

    /**
     * updates an existing user
     *
     * @param entity - the user with the new data; must not be null and must have an id
     * @return null - if the user was updated, otherwise the entity (there is no user with its id)
     * @throws IllegalArgumentException          if entity or its id is null
     * @throws exceptions.ValidationException    if the user is not valid
     * @throws RepositoryException               if a database access error occurs
     *                                           or a constraint is violated (e.g. duplicate email)
     */
    @Override
    public User update(User entity) {
        if (entity == null || entity.getId() == null) {
            throw new IllegalArgumentException("entity and its id must not be null");
        }
        validator.validate(entity);                         // validare inainte de UPDATE

        String sql = "UPDATE users SET first_name = ?, last_name = ?, email = ?, password = ? WHERE id = ?";
        try (Connection connection = DriverManager.getConnection(url, username, password);
             PreparedStatement statement = connection.prepareStatement(sql)) {

            statement.setString(1, entity.getFirstName());
            statement.setString(2, entity.getLastName());
            statement.setString(3, entity.getEmail());
            statement.setString(4, entity.getPassword());
            statement.setLong(5, entity.getId());
            int rows = statement.executeUpdate();            // cate randuri s-au modificat
            return rows == 0 ? entity : null;                // 0 randuri = id-ul nu exista
        } catch (SQLException e) {
            throw new RepositoryException("Database error while updating user " + entity.getId() + ": " + e.getMessage(), e);
        }
    }
}